from questions import F,part

F('U1-F01',1,'Continuity and IVT',r'함수 $f$는 $x<1$에서 $x^2+a$, $x=1$에서 $b$, $x>1$에서 $3x-1$로 정의한다.',r'Define $f(x)=x^2+a$ for $x<1$, $f(1)=b$, and $f(x)=3x-1$ for $x>1$.',[
part(r'$x=1$에서 좌극한과 우극한을 구하라.',r'Find the left and right limits at $1$.',r'좌극한은 $1+a$, 우극한은 $2$이다. 함숫값 $b$는 이 극한 계산에 영향을 주지 않는다.',r'The left limit is $1+a$ and the right limit is $2$. The value $b$ does not determine either nearby limit.',3,'좌극한 1점; 우극한 1점; 점의 값과 극한 구별 1점','Left limit 1; right limit 1; distinguish the point value 1'),
part(r'$f$가 모든 실수에서 연속이 되게 하는 $a,b$를 구하라.',r'Find $a,b$ that make $f$ continuous everywhere.',r'$1+a=2=b$이므로 $a=1$, $b=2$이다. 각 조각은 다항함수이므로 다른 점에서는 연속이다.',r'Match both limits and the value: $1+a=2=b$. Thus $a=1,b=2$; each polynomial piece is continuous elsewhere.',3,'세 값 일치 조건 1점; a 값 1점; b 값과 다른 점의 연속성 1점','Matching condition 1; value of a 1; value of b and remaining continuity 1'),
part(r'(b)의 값을 사용하라. $f(c)=3$인 $c\in(0,2)$의 존재를 정리로 설명하고 한 값을 구하라.',r'Use part (b). Justify the existence of $c\in(0,2)$ with $f(c)=3$, and find one such value.',r'$[0,2]$에서 연속이고 $f(0)=1<3<5=f(2)$이므로 중간값정리를 적용한다. 오른쪽 조각에서 $3c-1=3$을 풀면 $c=4/3$이다.',r'Continuity on $[0,2]$ and $f(0)=1<3<5=f(2)$ justify IVT. Solving $3c-1=3$ gives $c=4/3$.',3,'연속성 1점; 목표값 사이와 정리 1점; c 계산 1점','Continuity 1; straddling and IVT 1; computed c 1','solve(3*x-1-3,x)[0]','4/3')])

F('U1-F02',1,'Graph limits and a theorem hypothesis',r'그림의 그래프는 두 선분 $(-1,0)$에서 $(1,2)$, $(1,2)$에서 $(3,0)$으로 이어지지만 $(1,2)$는 빈 점이고 실제 함숫값은 $g(1)=4$이다.',r'The graph follows segments from $(-1,0)$ to $(1,2)$ to $(3,0)$, with a hole at $(1,2)$ and actual value $g(1)=4$.',[
part(r'$x=1$에서 양쪽 극한과 함숫값을 각각 구하라.',r'Find the two-sided limit and the function value at $1$.',r'좌우 극한은 모두 $2$이므로 양쪽 극한은 $2$이다. 채운 점에 의해 $g(1)=4$이다.',r'Both one-sided limits are $2$, so the limit is $2$. The filled point gives $g(1)=4$.',3,'좌극한 1점; 우극한과 양쪽 극한 1점; 실제 값 1점','Left limit 1; right and two-sided limit 1; actual value 1'),
part(r'한 점의 값만 바꾸어 $x=1$에서 연속이 되게 하라.',r'Redefine one value to make $g$ continuous at $1$.',r'$g(1)=2$로 다시 정의한다. 주변의 그래프를 바꾸지 않으면서 극한과 함숫값을 일치시킨다.',r'Redefine $g(1)=2$. This matches the existing limit without changing nearby values.',3,'기존 극한 2 확인 1점; 재정의 1점; 일치 조건 설명 1점','Identify limit 2 1; redefinition 1; matching explanation 1'),
part(r'원래 함수에 대해 $g(0)=1$, $g(1)=4$이다. 중간값정리로 $[0,1]$에서 값 $3$을 가진다고 할 수 있는가? 실제로 그런 점이 있는가?',r'For the original function, $g(0)=1$ and $g(1)=4$. Can IVT guarantee the value $3$ on $[0,1]$? Does such a point actually exist?',r'아니다. $x=1$에서 불연속이므로 정리의 가정이 깨진다. $0\le x<1$에서 $g(x)=x+1<2$이고 끝점에서는 $4$이므로 값 $3$인 점도 없다.',r'No. Discontinuity at $1$ violates IVT. For $0\le x<1$, values are $x+1<2$, and the endpoint value is $4$, so no value equals $3$.',3,'정리 적용 불가 1점; 깨진 연속성 가정 1점; 실제 값 범위로 비존재 설명 1점','Reject IVT application 1; identify failed hypothesis 1; prove no value 3 1')],figure='hole')

F('U2-F01',2,'Derivative definition and tangent',r'$f(x)=x^3-2x$이다.',r'Let $f(x)=x^3-2x$.',[
part(r'차분몫의 극한을 직접 전개하여 $f\prime(-1)$을 구하라.',r'Expand the difference quotient to find $f\prime(-1)$ from the definition.',r'$f(-1)=1$이고 $(f(-1+h)-f(-1))/h=1-3h+h^2$이다. 극한은 $1$이다.',r'Here $f(-1)=1$ and the quotient simplifies to $1-3h+h^2$. Its limit is $1$.',3,'올바른 차분몫 1점; 전개와 약분 1점; 극한 1점','Correct quotient 1; expansion and simplification 1; limit 1','limit((((-1+h)**3-2*(-1+h))-1)/h,h,0)','1'),
part(r'$x=-1$에서 접선식을 구하라.',r'Find the tangent line at $x=-1$.',r'점은 $(-1,1)$이고 기울기는 $1$이다. 따라서 $y-1=x+1$, 즉 $y=x+2$이다.',r'The point is $(-1,1)$ and slope is $1$, giving $y-1=x+1$, or $y=x+2$.',3,'접점 1점; 기울기 1점; 접선식 1점','Point 1; slope 1; line equation 1'),
part(r'$f^{\prime\prime}(-1)$을 구하고 이것이 접선의 기울기와 같은 정보인지 설명하라.',r'Find $f^{\prime\prime}(-1)$ and explain whether it is the tangent slope.',r'$f\prime=3x^2-2$, $f^{\prime\prime}=6x$이므로 값은 $-6$이다. 이는 도함수의 변화율이며 접선 기울기 $f\prime(-1)=1$과 다른 정보이다.',r'The second derivative is $6x$, so its value is $-6$. It measures change in the derivative, not the tangent slope $1$.',3,'첫 도함수 1점; 둘째 도함수와 값 1점; 의미 구별 1점','First derivative 1; second derivative and value 1; distinguish meanings 1','diff(x**3-2*x,x,2).subs(x,-1)','-6')])

F('U2-F02',2,'Rates from a table',r'$P(t)$는 온실 식물의 높이(cm)이며 $t$의 단위는 주이다. $P$는 미분가능하다. 표를 사용하라.',r'$P(t)$ is plant height in centimeters, where $t$ is weeks. Assume $P$ is differentiable and use the table.',[
part(r'$t=1,3$의 값을 사용하여 $P\prime(2)$를 추정하고 단위를 쓰라.',r'Use $t=1,3$ to estimate $P\prime(2)$ and give units.',r'$(10-3.5)/(3-1)=3.25$ cm/주이다. 정확한 도함수가 아니라 할선으로 얻은 추정이다.',r'The estimate is $(10-3.5)/2=3.25$ centimeters per week, a secant estimate rather than an exact derivative.',3,'차분몫 1점; 계산 1점; 단위와 추정 표시 1점','Secant expression 1; value 1; units and estimate 1','(10-Rational(7,2))/2','13/4'),
part(r'$[0,3]$에서 높이의 평균변화율을 구하라.',r'Find the average height rate on $[0,3]$.',r'$(P(3)-P(0))/3=(10-2)/3=8/3$ cm/주이다.',r'The average rate is $(10-2)/3=8/3$ centimeters per week.',3,'끝점의 변화량 1점; 구간 길이로 나눔 1점; 값과 단위 1점','Endpoint change 1; divide by interval length 1; result and units 1','Rational(10-2,3)','8/3'),
part(r'(a)의 추정 기울기로 $P(2.2)$를 근사하라.',r'Use the estimated slope in (a) to approximate $P(2.2)$.',r'$P(2.2)\approx6+3.25(0.2)=6.65$ cm이다. 추정 기울기를 사용한 국소 선형근사이다.',r'Use $P(2.2)\approx6+3.25(0.2)=6.65$ centimeters, a local linear estimate.',3,'기준값 6 1점; 변화량 곱 1점; 근삿값과 단위 1점','Base value 1; slope times change 1; estimate and units 1','6+Rational(13,4)*Rational(1,5)','133/20')],table={'headers':['t','P(t)'],'rows':[['0','2'],['1','3.5'],['2','6'],['3','10']]})

F('U3-F01',3,'Implicit first and second derivatives',r'원 $x^2+y^2=25$ 위의 점 $(3,4)$를 생각하라.',r'Consider the point $(3,4)$ on $x^2+y^2=25$.',[
part(r'$dy/dx$를 $x,y$로 나타내고 해당 점에서 값을 구하라.',r'Find $dy/dx$ in terms of $x,y$ and evaluate it at the point.',r'$2x+2yy\prime=0$에서 $y\prime=-x/y$이다. 점에서 기울기는 $-3/4$이다.',r'Implicit differentiation gives $y\prime=-x/y$, hence $-3/4$.',3,'음함수 미분 1점; y 도함수 고립 1점; 점 대입 1점','Implicit differentiation 1; isolate derivative 1; evaluation 1','(-x/y).subs({x:3,y:4})','-3/4'),
part(r'해당 점에서 접선식을 구하라.',r'Find the tangent line at the point.',r'$y-4=-(3/4)(x-3)$이다. $x=3$을 대입하면 원래 점을 지난다.',r'The tangent line is $y-4=-(3/4)(x-3)$.',3,'접점 1점; 기울기 연결 1점; 직선식 1점','Point 1; slope 1; line equation 1'),
part(r'$d^2y/dx^2$의 해당 점에서의 값을 구하라.',r'Find $d^2y/dx^2$ at the point.',r'$y^{\prime\prime}=-1/y+xy\prime/y^2=-1/y-x^2/y^3=-(x^2+y^2)/y^3$이다. 따라서 $-25/64$이다.',r'Differentiate $-x/y$ to obtain $y^{\prime\prime}=-1/y+xy\prime/y^2=-(x^2+y^2)/y^3$. The value is $-25/64$.',3,'곱 또는 몫 미분 1점; y 의존성 반영 1점; 최종값 1점','Differentiate quotient 1; include dependence of y 1; result 1','(-1/y-x**2/y**3).subs({x:3,y:4})','-25/64')])

F('U3-F02',3,'An inverse and a composition',r'$f(x)=x^3+x$이고 $g=f^{-1}$이다.',r'Let $f(x)=x^3+x$ and $g=f^{-1}$.',[
part(r'역함수가 존재하는 이유를 설명하고 $g(10)$을 구하라.',r'Explain why the inverse exists and find $g(10)$.',r'$f\prime=3x^2+1>0$이고 $f$는 양 끝에서 모든 실숫값을 지나므로 실수 전체에서 일대일 대응이다. $f(2)=10$이어서 $g(10)=2$이다.',r'The derivative is always positive and the polynomial has unbounded range in both directions, so it is a bijection on the reals. Since $f(2)=10$, $g(10)=2$.',3,'양의 도함수 1점; 역함수 가능성 설명 1점; g 값 1점','Positive derivative 1; inverse justification 1; value 1'),
part(r'$g\prime(10)$을 구하라.',r'Find $g\prime(10)$.',r'$f\prime(2)=13$이므로 $g\prime(10)=1/13$이다.',r'The corresponding original input is $2$, so $g\prime(10)=1/f\prime(2)=1/13$.',3,'대응 입력 2 1점; 원래 도함수 13 1점; 역수 1점','Corresponding input 1; original derivative 1; reciprocal 1','1/diff(x**3+x,x).subs(x,2)','1/13'),
part(r'$H(x)=g(5x)$일 때 $H\prime(2)$를 구하라.',r'If $H(x)=g(5x)$, find $H\prime(2)$.',r'연쇄법칙으로 $H\prime(2)=5g\prime(10)=5/13$이다.',r'The chain rule gives $H\prime(2)=5g\prime(10)=5/13$.',3,'연쇄법칙 1점; 입력 10 1점; 값 1점','Chain factor 1; correct inverse input 1; value 1','5/diff(x**3+x,x).subs(x,2)','5/13')])

F('U4-F01',4,'Motion and local approximation',r'입자의 위치는 $s(t)=t^3-6t^2+9t$ m이고 $0\le t\le4$에서 $t$의 단위는 s이다.',r'A particle has position $s(t)=t^3-6t^2+9t$ meters for $0\le t\le4$, with time in seconds.',[
part(r'속도와 가속도의 식을 구하라.',r'Find formulas for velocity and acceleration.',r'$v=3t^2-12t+9$ m/s, $a=6t-12$ m/s$^2$이다.',r'$v=3t^2-12t+9$ meters per second and $a=6t-12$ meters per second squared.',3,'위치 미분 1점; 속도 미분 1점; 두 단위 1점','Position derivative 1; velocity derivative 1; both units 1'),
part(r'$t=1.5$에서 움직이는 방향과 빨라지는지를 근거와 함께 설명하라.',r'At $t=1.5$, justify the direction and whether the particle is speeding up.',r'$v(1.5)=-9/4$, $a(1.5)=-3$이다. 음의 방향으로 움직이고 두 부호가 같아서 빨라진다.',r'Here $v=-9/4$ and $a=-3$. Motion is negative and matching signs mean speed increases.',3,'속도 부호 1점; 가속도 부호 1점; 방향과 속력 결론 1점','Velocity sign 1; acceleration sign 1; both conclusions 1'),
part(r'$t=1.5$에서의 선형근사로 $s(1.6)$을 구하라.',r'Use linearization at $1.5$ to estimate $s(1.6)$.',r'$s(1.5)=27/8$이므로 $s(1.6)\approx27/8-(9/4)(0.1)=3.15$ m이다.',r'The base value is $27/8$, so $s(1.6)\approx27/8-(9/4)(0.1)=3.15$ meters.',3,'기준 위치 1점; 속도 곱하기 시간차 1점; 근삿값과 단위 1점','Base position 1; velocity times time change 1; estimate and units 1','(t**3-6*t**2+9*t).subs(t,Rational(3,2))+diff(t**3-6*t**2+9*t,t).subs(t,Rational(3,2))*Rational(1,10)','63/20')])

F('U4-F02',4,'Conical tank',r'꼭짓점이 아래인 원뿔 탱크는 높이 $8$ cm, 윗반지름 $4$ cm이다. 물이 일정하게 $3\pi$ cm$^3$/s씩 들어온다. 한 순간 물의 높이는 $2$ cm이다.',r'An inverted cone has height $8$ cm and top radius $4$ cm. Water enters at $3\pi$ cm$^3$/s. At a certain instant its water depth is $2$ cm.',[
part(r'물의 부피 $V$를 물의 높이 $h$만으로 나타내라.',r'Express water volume using only depth $h$.',r'닮음에서 $r/h=1/2$이다. $V=\pi r^2h/3=\pi h^3/12$이다.',r'Similarity gives $r=h/2$, so $V=\pi h^3/12$.',3,'닮음 비 1점; 원뿔 부피식 1점; 한 변수식 1점','Similarity ratio 1; cone volume 1; one-variable expression 1'),
part(r'해당 순간 $dh/dt$를 구하라.',r'Find $dh/dt$ at that instant.',r'$V\prime=(\pi h^2/4)h\prime$이다. $3\pi=\pi h\prime$이므로 $h\prime=3$ cm/s이다.',r'Differentiate to get $V\prime=(\pi h^2/4)h\prime$. At $h=2$, the depth rate is $3$ cm/s.',3,'시간 미분 1점; 값 대입 1점; 값과 단위 1점','Time differentiation 1; substitution 1; value and units 1','(3*pi)/(pi*2**2/4)','3'),
part(r'$0.1$초 뒤의 물 높이를 선형근사하라. 실제 높이에 비해 과대인지 근거를 쓰라.',r'Linearly estimate the depth $0.1$ second later. Justify whether it overestimates the actual depth.',r'근사는 $2+3(0.1)=2.3$ cm이다. $h\prime=12/h^2$이므로 $h^{\prime\prime}=-24h\prime/h^3<0$이다. 이 짧은 구간에서 아래로 오목하므로 과대근사이다.',r'The estimate is $2.3$ cm. Since $h\prime=12/h^2$, $h^{\prime\prime}=-24h\prime/h^3<0$, so the tangent overestimates on the interval.',3,'선형근사 1점; 음의 둘째 도함수 1점; 과대근사 결론 1점','Linear estimate 1; negative second derivative 1; overestimate conclusion 1','2+3*Rational(1,10)','23/10')])

F('U5-F01',5,'Complete function analysis',r'$f(x)=x^3-6x^2+9x+1$을 $[0,4]$에서 분석하라.',r'Analyze $f(x)=x^3-6x^2+9x+1$ on $[0,4]$.',[
part(r'증가와 감소 구간 및 내부의 극대와 극소 위치를 근거와 함께 구하라.',r'Justify intervals of increase and decrease and locate interior local extrema.',r'$f\prime=3(x-1)(x-3)$이다. $(0,1),(3,4)$에서 증가, $(1,3)$에서 감소한다. 부호가 $+,-,+$로 바뀌어 $x=1$은 극대, $x=3$은 극소이다.',r'The derivative is $3(x-1)(x-3)$ with signs $+,-,+$. Increase occurs on $(0,1),(3,4)$ and decrease on $(1,3)$. The local maximum is at $1$ and minimum at $3$.',3,'도함수와 임계수 1점; 증감구간 1점; 부호변화와 극값 1점','Derivative and critical numbers 1; intervals 1; extrema with sign changes 1'),
part(r'절대최댓값과 절대최솟값 및 모든 달성 위치를 구하라.',r'Find absolute extreme values and every location attaining them.',r'$f(0)=1$, $f(1)=5$, $f(3)=1$, $f(4)=5$이다. 최대는 $5$로 $x=1,4$, 최소는 $1$로 $x=0,3$에서 달성된다.',r'Candidate values are $1,5,1,5$. The maximum $5$ occurs at $1,4$ and minimum $1$ at $0,3$.',3,'끝점 포함 후보 1점; 함숫값 비교 1점; 값과 모든 위치 1점','Include endpoints 1; compare values 1; values and all locations 1'),
part(r'변곡점을 구하고 오목성 변화를 설명하라.',r'Find the inflection point and explain the concavity change.',r'$f^{\prime\prime}=6x-12$는 $x=2$에서 음수에서 양수로 바뀐다. $f(2)=3$이므로 변곡점은 $(2,3)$이다.',r'The second derivative $6x-12$ changes from negative to positive at $2$. Since $f(2)=3$, the point is $(2,3)$.',3,'둘째 도함수 1점; 부호변화 1점; 좌표 1점','Second derivative 1; sign change 1; coordinates 1','(x**3-6*x**2+9*x+1).subs(x,2)','3')])

F('U5-F02',5,'Box optimization',r'한 변이 $18$ cm인 정사각형 종이의 네 모서리에서 한 변 $x$ cm인 정사각형을 잘라내고 접어 뚜껑 없는 상자를 만든다.',r'Cut squares of side $x$ cm from each corner of an $18$ cm square sheet and fold an open-top box.',[
part(r'부피함수와 물리적으로 가능한 $x$의 범위를 쓰라.',r'Write the volume function and physically feasible domain.',r'$V=x(18-2x)^2$이고 양의 높이와 밑변을 위해 $0<x<9$이다.',r'The volume is $V=x(18-2x)^2$ on $0<x<9$.',3,'높이 x 1점; 두 밑변과 부피식 1점; 정의역 1점','Height 1; base dimensions and volume 1; domain 1'),
part(r'최대 부피를 만드는 $x$와 그 부피를 근거와 함께 구하라.',r'Justify the maximizing cut size and find the maximum volume.',r'$V\prime=(18-2x)(18-6x)$이다. 정의역 내부의 임계수는 $3$이고 양에서 음으로 바뀐다. 양 끝 경계에서 부피는 $0$으로 가므로 최대는 $V(3)=432$ cm$^3$이다.',r'The derivative is $(18-2x)(18-6x)$. Its interior critical number $3$ changes derivative sign from positive to negative; boundary volumes tend to zero. Thus the maximum is $432$ cm$^3$.',3,'도함수와 x=3 1점; 최대 근거 1점; 부피와 단위 1점','Derivative and critical point 1; maximum justification 1; volume and units 1','(x*(18-2*x)**2).subs(x,3)','432'),
part(r'제작 장비 때문에 $0<x\le2$로 제한되면 최대 부피는?',r'If equipment restricts cuts to $0<x\le2$, what is the maximum volume?',r'이 구간에서 $V\prime>0$이므로 오른쪽 끝 $x=2$에서 최대이다. 부피는 $2(14)^2=392$ cm$^3$이다.',r'The volume increases throughout the restricted interval, so the maximum is at $x=2$, giving $392$ cm$^3$.',3,'새 정의역 1점; 증가 근거와 끝점 1점; 부피 1점','Restricted domain 1; increasing and endpoint 1; volume 1','(x*(18-2*x)**2).subs(x,2)','392')])

F('U6-F01',6,'Accumulation from a graph',r'그림은 $f$의 그래프이다. $F(x)=1+\int_0^x f(t)\,dt$로 정의하고 $0\le x\le4$로 제한한다.',r'The graph shows $f$. Define $F(x)=1+\int_0^x f(t)\,dt$ on $0\le x\le4$.',[
part(r'$F(3)$과 $F(4)$를 구하라.',r'Find $F(3)$ and $F(4)$.',r'$[0,3]$의 양의 삼각형 넓이는 $3$이고 $[3,4]$의 음의 삼각형 기여는 $-1$이다. 따라서 $F(3)=4$, $F(4)=3$이다.',r'The positive area is $3$ and the final negative triangle contributes $-1$. Hence $F(3)=4,F(4)=3$.',3,'양의 넓이 1점; 음의 기여 1점; 초기값 포함 두 값 1점','Positive area 1; negative contribution 1; both values with initial constant 1'),
part(r'$F\prime(2)$와 $F^{\prime\prime}(2)$를 구하라.',r'Find $F\prime(2)$ and $F^{\prime\prime}(2)$.',r'$F\prime=f$이므로 $F\prime(2)=1$이다. 해당 선분 기울기는 $-1$이므로 $F^{\prime\prime}(2)=-1$이다.',r'FTC gives $F\prime(2)=f(2)=1$ and $F^{\prime\prime}(2)=f\prime(2)=-1$.',3,'기본정리 연결 1점; 함수 높이 1점; 그래프 기울기 1점','FTC connection 1; graph height 1; graph slope 1'),
part(r'$F$의 절대최댓값과 그 위치를 근거와 함께 구하라.',r'Justify the absolute maximum of $F$ and its location.',r'$f>0$인 $(0,3)$에서 $F$는 증가하고 $f<0$인 $(3,4)$에서 감소한다. 따라서 $x=3$에서 절대최댓값 $4$를 가진다.',r'Because $F\prime=f$, $F$ increases before $3$ and decreases afterward. Its absolute maximum is $4$ at $3$.',3,'도함수 연결 1점; 부호에 따른 증감 1점; 위치와 최댓값 1점','Derivative connection 1; sign-based monotonicity 1; location and value 1')],figure='accumulation')

F('U6-F02',6,'Tabular integration and units',r'$r(t)$는 물의 유입률(L/min)이다. 처음에 물이 $20$ L 있다. 표에 없는 시간에도 $r$는 연속이며, 구간 전체에서 물은 유입만 된다.',r'$r(t)$ is inflow in liters per minute. Initially a tank contains $20$ liters. Assume $r$ is continuous and water only enters.',[
part(r'표의 세 구간에 대해 왼쪽 리만합으로 $\int_0^6r(t)\,dt$를 추정하라.',r'Estimate $\int_0^6r(t)\,dt$ with a left Riemann sum on the three tabulated intervals.',r'$2\cdot3+3\cdot5+1\cdot4=25$ L이다. 구간 폭은 각각 $2,3,1$이다.',r'The unequal-width sum is $2(3)+3(5)+1(4)=25$ liters.',3,'각 구간 폭 1점; 왼쪽 높이 선택 1점; 합과 단위 1점','Interval widths 1; left heights 1; result and units 1','2*3+3*5+1*4','25'),
part(r'같은 구간들에 사다리꼴합을 사용하라.',r'Use trapezoids over the same intervals.',r'$2(3+5)/2+3(5+4)/2+(4+7)/2=27$ L이다.',r'The trapezoidal estimate is $8+13.5+5.5=27$ liters.',3,'평균 높이들 1점; 폭 적용 1점; 결과와 단위 1점','Averaged heights 1; apply widths 1; result and units 1','2*Rational(3+5,2)+3*Rational(5+4,2)+Rational(4+7,2)','27'),
part(r'(b)로 $t=6$의 물의 양과 $[0,6]$에서 평균유입률을 추정하라.',r'Use (b) to estimate volume at $6$ and average inflow on $[0,6]$.',r'물의 양은 $20+27=47$ L, 평균유입률은 $27/6=4.5$ L/min이다.',r'Estimated final volume is $47$ liters and average inflow is $4.5$ liters per minute.',3,'초기량 더하기 1점; 구간 길이로 나눔 1점; 두 단위 1점','Add initial amount 1; divide by duration 1; both units 1')],table={'headers':['t','r(t)'],'rows':[['0','3'],['2','5'],['5','4'],['6','7']]})

F('U7-F01',7,'Separation and concavity',r'$y\prime=x(y-1)$이고 $y(0)=3$이다.',r'Consider $y\prime=x(y-1)$ with $y(0)=3$.',[
part(r'기울기가 0인 점들의 집합을 설명하고 초기점의 접선 기울기를 구하라.',r'Describe where the slope field has zero slope and find the initial tangent slope.',r'$x(y-1)=0$이므로 $x=0$ 또는 $y=1$에서 기울기가 0이다. 초기점 $(0,3)$의 기울기도 $0$이다.',r'Zero slope occurs when $x=0$ or $y=1$. The initial point therefore has slope $0$.',3,'x=0 1점; y=1 1점; 초기 기울기 1점','Vertical zero-slope line 1; horizontal line 1; initial slope 1'),
part(r'초기조건을 만족하는 해를 구하라.',r'Solve the initial-value problem.',r'$dy/(y-1)=x\,dx$이므로 $\ln|y-1|=x^2/2+C$이다. $y(0)=3$으로부터 $y=1+2e^{x^2/2}$이다.',r'Separate and integrate to get $y-1=Ce^{x^2/2}$. The initial value gives $C=2$.',3,'변수분리 1점; 적분과 상수 결정 1점; 명시적 해 1점','Separation 1; integration and constant 1; explicit solution 1','diff(1+2*exp(x**2/2),x)-x*((1+2*exp(x**2/2))-1)','0'),
part(r'이 해의 오목성을 모든 실수에서 설명하라.',r'Determine the solution concavity on the real line.',r'$y^{\prime\prime}=(y-1)+xy\prime=(y-1)(1+x^2)$이다. 해에서 $y-1>0$이므로 모든 실수에서 위로 오목하다.',r'Differentiating gives $y^{\prime\prime}=(y-1)(1+x^2)$. Both factors are positive on this solution, so it is concave up everywhere.',3,'다시 미분 1점; 식 정리 1점; 양의 부호와 결론 1점','Differentiate again 1; simplify 1; sign and conclusion 1')])

F('U7-F02',7,'Temperature model',r'물체의 온도는 $T\prime=-k(T-18)$, $k>0$을 만족한다. $T(0)=82$, $T(10)=50$이며 시간은 분, 온도는 섭씨이다.',r'Temperature satisfies $T\prime=-k(T-18)$ with $k>0$, $T(0)=82$, and $T(10)=50$. Time is in minutes and temperature in degrees Celsius.',[
part(r'$T$를 $k,t$로 나타내라.',r'Express $T$ in terms of $k,t$.',r'$T-18=Ce^{-kt}$이고 초기조건으로 $C=64$이다. $T=18+64e^{-kt}$이다.',r'Solving gives $T-18=Ce^{-kt}$. The initial condition sets $C=64$.',3,'지수 형태 1점; 기준온도 반영 1점; 초기 상수 1점','Exponential form 1; baseline temperature 1; initial constant 1'),
part(r'$k$를 정확히 구하라.',r'Find the exact value of $k$.',r'$50=18+64e^{-10k}$에서 $e^{-10k}=1/2$이므로 $k=(\ln2)/10$이다.',r'The measurement gives $e^{-10k}=1/2$, so $k=(\ln2)/10$ per minute.',3,'측정값 대입 1점; 로그를 취함 1점; k와 단위 1점','Substitute measurement 1; logarithm 1; k and units 1','-log(Rational(1,2))/10','log(2)/10'),
part(r'온도가 $26$이 되는 시각을 구하라.',r'Find the time when temperature reaches $26$.',r'주변온도와의 차이는 $8$로 처음 $64$의 $1/8$이다. 반감기 $10$분이 세 번 지나므로 $t=30$분이다.',r'The excess temperature falls from $64$ to $8$, or three halvings. Thus $t=30$ minutes.',3,'온도차 비율 1점; 지수식 또는 반감기 풀이 1점; 시각과 단위 1점','Excess-temperature ratio 1; exponential or half-life solution 1; time and units 1','-log(Rational(8,64))/(log(2)/10)','30')])

F('U8-F01',8,'Distance and position extrema',r'$v(t)=(t-1)(t-3)$ m/s, $s(0)=2$ m이고 $0\le t\le4$이다.',r'A particle has $v(t)=(t-1)(t-3)$ m/s, $s(0)=2$ meters, and $0\le t\le4$.',[
part(r'$s(4)$를 구하라.',r'Find $s(4)$.',r'변위는 $\int_0^4(t^2-4t+3)\,dt=4/3$이다. 초기위치를 더해 $s(4)=10/3$ m이다.',r'Displacement is $4/3$, so adding the initial position gives $s(4)=10/3$ meters.',3,'속도 적분 1점; 변위 계산 1점; 초기위치와 단위 1점','Velocity integral 1; displacement 1; initial position and units 1','2+integrate((t-1)*(t-3),(t,0,4))','10/3'),
part(r'총 이동거리를 구하라.',r'Find total distance traveled.',r'속도는 $+,-,+$의 부호를 가지며 $1,3$에서 바뀐다. 세 구간 절댓값 적분의 합은 $4/3+4/3+4/3=4$ m이다.',r'Split at $1,3$ and sum absolute signed integrals: $4/3+4/3+4/3=4$ meters.',3,'영점과 부호 1점; 절댓값 구간 분할 1점; 거리와 단위 1점','Zeros and signs 1; absolute-value split 1; distance and units 1','integrate((t-1)*(t-3),(t,0,1))-integrate((t-1)*(t-3),(t,1,3))+integrate((t-1)*(t-3),(t,3,4))','4'),
part(r'$s$의 절대최댓값 및 모든 달성 시각을 구하라.',r'Find the absolute maximum position and all times attaining it.',r'후보 $t=0,1,3,4$에서 위치는 각각 $2,10/3,2,10/3$이다. 최대위치는 $10/3$ m이고 시각은 $t=1,4$이다.',r'At candidate times $0,1,3,4$, positions are $2,10/3,2,10/3$. The maximum $10/3$ occurs at $1$ and $4$.',3,'끝점 포함 후보 1점; 위치 비교 1점; 최댓값과 모든 시각 1점','Candidates including endpoints 1; position comparison 1; value and all times 1')])

F('U8-F02',8,'Area and two rotation axes',r'$R$은 $y=x$와 $y=x^2$로 둘러싸인 유계영역이다.',r'Let $R$ be the bounded region between $y=x$ and $y=x^2$.',[
part(r'교점과 영역의 넓이를 구하라.',r'Find the intersection inputs and area.',r'교점 입력은 $0,1$이다. 넓이는 $\int_0^1(x-x^2)\,dx=1/6$이다.',r'Intersections occur at $0,1$ and area is $\int_0^1(x-x^2)\,dx=1/6$.',3,'교점 1점; 위아래 순서와 적분 1점; 넓이 1점','Intersections 1; ordered integrand 1; area 1','integrate(x-x**2,(x,0,1))','1/6'),
part(r'$R$을 $x$축 둘레로 회전한 부피를 구하라.',r'Find the volume when $R$ revolves about the $x$-axis.',r'$R_{out}=x$, $R_{in}=x^2$이다. $V=\pi\int_0^1(x^2-x^4)\,dx=2\pi/15$이다.',r'Outer and inner radii are $x$ and $x^2$. The washer integral is $2\pi/15$.',3,'반지름 두 개 1점; 제곱의 차 적분 1점; 부피 1점','Both radii 1; difference-of-squares integral 1; volume 1','pi*integrate(x**2-x**4,(x,0,1))','2*pi/15'),
part(r'$R$을 직선 $y=2$ 둘레로 회전한 부피를 구하라.',r'Find the volume when $R$ revolves about $y=2$.',r'바깥 반지름은 $2-x^2$, 안쪽은 $2-x$이다. $V=\pi\int_0^1((2-x^2)^2-(2-x)^2)\,dx=8\pi/15$이다.',r'The outer radius is $2-x^2$ and inner radius is $2-x$. The washer integral evaluates to $8\pi/15$.',3,'이동한 축까지 거리 1점; 와셔 적분 1점; 계산 1점','Distances from shifted axis 1; washer integral 1; evaluation 1','pi*integrate((2-x**2)**2-(2-x)**2,(x,0,1))','8*pi/15')],figure='area')
